// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        bool success;
        bytes memory data = abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[0], v);
        (bool callSuccess,) = caddress.call(data);
        vm.assume(callSuccess);
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            success = ret;
        } catch {
            success = false;
        }
        assertTrue(success == true);
    }
}

